    let (key, value) = assignment.split_once('=').ok_or_else(|| {
        anyhow::anyhow!("invalid assignment '{}': expected key=value", assignment)
    })?;
    xt::ts_cmd::set_value(&crate_name, key, value, tspec.as_deref())?;
}

